import { createHash } from "node:crypto";
import { MAX_EVIDENCE_BYTES } from "./upload-validation";

/** Provider contract, not a production adapter. Capability declarations must be
 * verified against a real provider before use; declaring them is not proof.
 * Every key is generated by the server after authorization, never a client URL.
 * Keys are create-once: an existing object must never be replaced by put.
 */
export interface PrivateUploadStorage {
  readonly capabilities: {
    privateObjects: boolean;
    conditionalCreate: boolean;
    versionedDelete: boolean;
  };
  putPrivateIfAbsent(input: { key: string; bytes: Uint8Array; sha256: string }): Promise<
    { status: "created"; version: string } | { status: "exists" } | { status: "unknown" }
  >;
  /** SHA-256 must describe the object's actual bytes; an ETag is not sufficient.
   * A version argument addresses that immutable version, not the latest object.
   * Timeout, denied access and provider failure are unknown, never missing.
   */
  headPrivate(key: string, version?: string): Promise<
    { status: "found"; version: string; bytes: number; sha256: string; private: boolean }
    | { status: "missing" } | { status: "unknown" }
  >;
  /** Must enforce maxBytes before/during reading, never return an unbounded body. */
  readPrivate(key: string, version: string, maxBytes: number): Promise<
    { status: "found"; bytes: Uint8Array } | { status: "missing" } | { status: "unknown" }
  >;
  /** Atomic version precondition. Unknown outcomes must be reconciled, not retried
   * as an unconditional delete. Live-reference authorization belongs to caller. */
  deletePrivateIfVersion(key: string, version: string): Promise<
    { status: "deleted" } | { status: "missing" } | { status: "version_mismatch" } | { status: "unknown" }
  >;
}

export type PrivateUploadReceipt = { key: string; version: string; bytes: number; sha256: string };
export type PrivateUploadResult =
  | { status: "confirmed"; receipt: PrivateUploadReceipt }
  | { status: "rejected"; reason: string }
  | { status: "unknown"; reason: string }
  | { status: "conflict"; reason: string };

/** Standalone pre-integration receiver. Does NOT authorize, publish an Asset,
 * scan malware, mark an intent ready, release quota, retry, or delete objects.
 * The issued-only intent foundation MUST NOT call this until durable receiving/
 * reconciliation states exist. A confirmed receipt means private storage only.
 * Callers must impose a transport timeout/cancellation policy on the source.
 */
export async function receivePrivateUpload(
  adapter: PrivateUploadStorage,
  input: { key: string; source: AsyncIterable<Uint8Array>; expectedBytes: number },
): Promise<PrivateUploadResult> {
  const { key, expectedBytes } = input;
  if (typeof key !== "string" || !/^[A-Za-z0-9][A-Za-z0-9/_-]{0,255}$/.test(key) || key.includes("//") || key.endsWith("/")) {
    return { status: "rejected", reason: "invalid_key" };
  }
  if (!Number.isSafeInteger(expectedBytes) || expectedBytes < 1 || expectedBytes > MAX_EVIDENCE_BYTES) {
    return { status: "rejected", reason: "invalid_size" };
  }
  if (adapter.capabilities?.privateObjects !== true || adapter.capabilities?.conditionalCreate !== true || adapter.capabilities?.versionedDelete !== true) {
    return { status: "rejected", reason: "unsupported_storage" };
  }

  // One bounded allocation avoids retaining arbitrary source-owned buffers or
  // allocating a second concatenation buffer. Copy before requesting next chunk.
  const bytes = Buffer.alloc(expectedBytes);
  let received = 0, chunks = 0;
  try {
    for await (const chunk of input.source) {
      if (!(chunk instanceof Uint8Array) || ++chunks > 65536) return { status: "rejected", reason: "invalid_source" };
      if (chunk.byteLength > expectedBytes - received) return { status: "rejected", reason: "size_exceeded" };
      bytes.set(chunk, received);
      received += chunk.byteLength;
    }
  } catch {
    return { status: "rejected", reason: "source_failed" };
  }
  if (received !== expectedBytes) return { status: "rejected", reason: "size_mismatch" };
  const sha256 = createHash("sha256").update(bytes).digest("hex");

  try {
    const outcome = await adapter.putPrivateIfAbsent({ key, bytes, sha256 });
    if (outcome.status === "unknown") return { status: "unknown", reason: "put_unconfirmed" };
    if (outcome.status !== "created" && outcome.status !== "exists") return { status: "unknown", reason: "invalid_put_result" };
    if (outcome.status === "created" && (typeof outcome.version !== "string" || !outcome.version || outcome.version.length > 1024)) return { status: "unknown", reason: "invalid_version" };
    const head = await adapter.headPrivate(key, outcome.status === "created" ? outcome.version : undefined);
    if (head.status !== "found") return { status: "unknown", reason: "object_unconfirmed" };
    if (head.private !== true || typeof head.version !== "string" || !head.version || head.version.length > 1024) return { status: "unknown", reason: "private_version_unconfirmed" };
    if (outcome.status === "created" && outcome.version !== head.version) return { status: "unknown", reason: "version_mismatch" };
    if (head.bytes !== received || head.sha256 !== sha256) {
      return outcome.status === "exists"
        ? { status: "conflict", reason: "existing_content_mismatch" }
        : { status: "unknown", reason: "stored_content_mismatch" };
    }
    return { status: "confirmed", receipt: { key, version: head.version, bytes: received, sha256 } };
  } catch {
    // A failed acknowledgement is not proof of failed storage. Never compensate
    // by deleting or releasing a reservation here; durable reconciliation owns it.
    return { status: "unknown", reason: "storage_unconfirmed" };
  }
}
